-- The SUMO-GRIP code key (Code keys -> Parting -> SUMO-GRIP), from the ISCAR
-- e-catalog's SUMO-GRIP families (TAGB / TAGBA inserts, TGBHR/L toolholders);
-- kept if one exists.
INSERT INTO "AppSetting" ("key", "value") VALUES ('codekey.sumogrip', $ck${"title": "SUMO-GRIP code key – inserts and tools", "subtitle": "Single-ended utility inserts (TAGB / TAGBA) for heavy duty grooving, turning and parting, and their TGBHR/L toolholders", "example": "TAGB 608Y", "decoder": "sumo-grip", "sections": [{"key": "i-family", "title": "Insert – family", "sample": "TAGB", "rows": [{"code": "TAGB", "meaning": "SUMO-GRIP single-ended utility insert for grooving, turning and parting"}, {"code": "TAGBA", "meaning": "SUMO-GRIP single-ended utility insert, A version (width and radius x10)"}]}, {"key": "i-width", "title": "Insert – width and corner radius", "sample": "608", "rows": [{"code": "###", "meaning": "Width (first digit) and corner radius x10 (e.g. 608 = 6 mm, R0.8; 630 = 6 mm, R3.0 full radius)"}, {"code": "####", "meaning": "Width (first two digits) and corner radius x10 (e.g. 1008 = 10 mm, R0.8; 1415 = 14 mm, R1.5)"}, {"code": "##-##", "meaning": "TAGBA: width and corner radius x10 (e.g. 80-40 = 8 mm, R4.0 full radius)"}]}, {"key": "i-chip", "title": "Chipformer", "sample": "Y", "rows": [{"code": "Y", "meaning": "Utility chipformer for grooving, turning and parting (inferred)"}, {"code": "H", "meaning": "Chipformer for heavy duty / hard applications (inferred)"}, {"code": "YZ", "meaning": "TAGBA chipformer (inferred)"}]}, {"key": "t-family", "title": "Tool – family", "rows": [{"code": "TGBH", "meaning": "Toolholders for heavy duty groove-turn and parting applications (TGBHR / TGBHL)"}]}, {"key": "t-hand", "title": "Tool – hand", "rows": [{"code": "R", "meaning": "Right-hand"}, {"code": "L", "meaning": "Left-hand"}]}, {"key": "t-height", "title": "Tool – shank", "rows": [{"code": "##", "meaning": "Shank size in mm (20, 25, 32, 40)"}]}, {"key": "t-width", "title": "Tool – insert width", "rows": [{"code": "#", "meaning": "Insert width in mm (6, 8)"}, {"code": "##", "meaning": "Insert width in mm (10, 12, 14)"}]}, {"key": "t-suffix", "title": "Tool – suffixes", "rows": [{"code": "C", "meaning": "With coolant supply"}, {"code": "T##", "meaning": "Maximum cutting depth in mm (e.g. T20, T40)"}, {"code": "JHP", "meaning": "Channels for high-pressure coolant"}]}]}$ck$)
ON CONFLICT ("key") DO NOTHING;
